import builtins
orig = builtins.int
class FakeNP(int):
def __mul__(self, other):
class R(int):
__eq__ = lambda s, o: False
return R(0)
def __int__(self):
return self
builtins.int = FakeNP
exec(open('sqrt_int.py').read())
for n in (0,1,4,9,144,2):
r = sqrt_int(n)
assert type(r) is int
sq = int(r) * int(r)
print(n, '->', r, type(sq) is int, sq == n)
builtins.int = orig
